create or replace function gldd_private.driver_day(business uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare current_day public.bjta_days; result_rows jsonb; result_events jsonb;
begin
 if not gldd_private.has_business_role(business,array['business_admin','driver']) then raise exception 'Driver access required';end if;
 select * into current_day from public.bjta_days where business_id=business and not archived order by created_at desc limit 1;
 if not found then return jsonb_build_object('days','[]'::jsonb,'rows','[]'::jsonb,'events','[]'::jsonb);end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'day_id',d.day_id,'status',d.status,'claimed_by',d.claimed_by,'assigned_to',d.assigned_to,'started_at',d.started_at,'completed_at',d.completed_at,'created_at',d.created_at,
 'amount_visible',coalesce(d.claimed_by=auth.uid() or d.assigned_to=auth.uid(),false),
 'paid',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then d.paid else false end,
 'payment_method',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then d.payment_method else null end,
 'details',jsonb_strip_nulls(jsonb_build_object('businessName',d.details->'businessName','name',d.details->'name','phone',d.details->'phone','address',d.details->'address','unit',d.details->'unit','notes',d.details->'notes','driver',d.details->'driver','priority',d.details->'priority','deadline',d.details->'deadline','routeOrder',d.details->'routeOrder','estimatedArrival',d.details->'estimatedArrival','lateEstimate',d.details->'lateEstimate','location',d.details->'location','mileage',d.details->'mileage','receiptId',case when d.claimed_by=auth.uid() then d.details->'receiptId' else null end,
 'price',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then d.details->'price' else null end,'qty',d.details->'qty','fee',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then d.details->'fee' else null end,
 'items',case when jsonb_typeof(d.details->'items')='array' then (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',i->'name','qty',i->'qty','price',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then i->'price' else null end))) from jsonb_array_elements(d.details->'items') i) else jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('name',case d.details->>'price' when '10' then 'Small tchaka' when '15' then 'Medium tchaka' when '20' then 'Large tchaka' else 'Order item' end,'qty',d.details->'qty','price',case when d.claimed_by=auth.uid() or d.assigned_to=auth.uid() then d.details->'price' else null end))) end))) order by d.created_at),'[]'::jsonb) into result_rows
 from public.bjta_deliveries d where d.day_id=current_day.id and
 ((d.status='ready' and (d.assigned_to is null or d.assigned_to=auth.uid())) or d.claimed_by=auth.uid() or d.assigned_to=auth.uid() or exists(select 1 from public.gldd_handoffs h where h.status='pending' and h.day_id=current_day.id and auth.uid() in(h.from_user,h.to_user,h.requested_by) and d.id=any(h.delivery_ids)));
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'day_id',e.day_id,'delivery_id',e.delivery_id,'actor_id',e.actor_id,'action',e.action,'details',jsonb_build_object('reason',e.details->'reason'),'happened_at',e.happened_at) order by e.happened_at desc),'[]'::jsonb) into result_events from public.bjta_events e where e.day_id=current_day.id and e.actor_id=auth.uid();
 return jsonb_build_object('days',jsonb_build_array(jsonb_build_object('id',current_day.id,'business_id',current_day.business_id,'delivery_date',current_day.delivery_date,'kitchen_address',current_day.kitchen_address,'archived',false,'created_at',current_day.created_at,'settings',jsonb_build_object('receiptName',current_day.settings->'receiptName','maps',coalesce(current_day.settings->>'maps','apple'),'drivers',coalesce((current_day.settings->>'drivers')::int,1),'driver1',current_day.settings->>'driver1','driver2',current_day.settings->>'driver2','kitchenLocation',current_day.settings->'kitchenLocation'))),'rows',result_rows,'events',result_events);
end $$;
create or replace function public.gldd_driver_day(business uuid) returns jsonb language sql stable set search_path='' as $$select gldd_private.driver_day(business);$$;
revoke all on function public.gldd_driver_day(uuid),gldd_private.driver_day(uuid) from public,anon;
grant execute on function public.gldd_driver_day(uuid),gldd_private.driver_day(uuid) to authenticated;
